<template><div class="pm-dashboard-layout" :class="{'pm-sidebar-hidden':hidden}"><AppSidebar :isOpen="open" @close="open=false"/><div class="pm-dashboard-main"><div class="pm-dashboard-topbar"><button class="pm-icon-btn pm-menu-btn" @click="open=!open">☰</button><button class="pm-icon-btn pm-hide-btn" @click="hidden=!hidden">←</button><div class="pm-topbar-page-title">Accidents & Incidents</div><div class="pm-topbar-search"><input class="form-control" v-model="search" placeholder="Search..."/></div><div class="pm-topbar-actions"><button class="pm-icon-btn">♧<span class="pm-topbar-dot">5</span></button><button class="pm-icon-btn">✉</button></div><div class="pm-topbar-user"><div class="pm-topbar-avatar">JD</div><span class="pm-topbar-name">John Doe</span></div></div><main class="ac"><header><div><h1>{{entry?'New Accident / Incident':'Accidents & Incidents'}}</h1><p>Dashboard　›　Vehicle Management　›　Accidents & Incidents</p></div><button class="btn btn-primary" @click="entry=!entry">{{entry?'← Back to List':'+ New Accident / Incident'}}</button></header><template v-if="!entry"><div class="summary"><article v-for="c in stats" :class="c.t"><b>{{c.icon}}</b><span>{{c.l}}<strong>{{c.v}}</strong><small>{{c.s}}</small></span></article></div><section class="filter"><input v-model="search" placeholder="Search by Report No., Incident Name, Location..."/><input type="date"/><select><option>All Types</option></select><select><option>All Statuses</option></select><select><option>All Vehicles</option></select><select><option>All Drivers</option></select><button class="btn btn-primary" @click="load">Apply Filters</button><button @click="search=''">Reset</button></section><section class="table"><p>Showing 1 to {{rows.length}} of {{rows.length}} records</p><table><thead><tr><th>#</th><th>Report No.</th><th>Incident Report Name</th><th>Incident Date</th><th>Time</th><th>Accident Type</th><th>Location</th><th>Vehicle No.</th><th>Driver Name</th><th>Status</th><th>Created By</th><th>Actions</th></tr></thead><tbody><tr v-for="(x,i) in rows" :key="x.id"><td>{{i+1}}</td><td>{{x.report_code}}</td><td>{{x.incident_report_name}}</td><td>{{date(x.incident_date)}}</td><td>{{x.incident_time}}</td><td>{{x.accident_type}}</td><td>{{x.location}}</td><td>{{x.vehicle_number}}</td><td>{{x.driver_name||'—'}}</td><td><em :class="'s'+x.status">{{x.status_label}}</em></td><td>{{x.created_by_name}}</td><td>⋮</td></tr></tbody></table></section></template><template v-else><div class="form"><section><h2>1.　Report Info</h2><label>Report No.<input value="Auto Generate" readonly></label><label>Report Date<input v-model="f.report_date" type="date"></label><label>Created By<input v-model="f.created_by_name"></label><label>Incident Report No.<input v-model="f.incident_report_no" placeholder="Auto Generate"></label><label class="wide">Incident Report Name<input v-model="f.incident_report_name" placeholder="Enter report name / title"></label></section><section><h2>2.　Accident Details</h2><label>Accident ID<input value="Auto Generate" readonly></label><label>Incident Date<input v-model="f.incident_date" type="date"></label><label>Time<input v-model="f.incident_time" type="time"></label><label>Location<input v-model="f.location"></label><label>Accident Type<select v-model="f.accident_type"><option>Collision</option><option>Breakdown</option><option>Minor Accident</option><option>Other</option></select></label><label class="wide">Description / Damage Details<textarea v-model="f.description"></textarea></label></section><section><h2>3.　Vehicle Info</h2><label>Vehicle Number<select v-model="f.vehicle_id"><option value="">Select Vehicle</option><option v-for="v in vehicles" :value="v.id">{{v.vehicle_number}}</option></select></label><label>Driver Name<select v-model="f.driver_id"><option value="">Select Driver</option><option v-for="d in drivers" :value="d.id">{{d.driver_name}}</option></select></label><label>Plate Number<input :value="vehicle?.plate_number||''" readonly></label><label>Make & Model<input :value="vehicle?vehicle.make_brand+' '+vehicle.model:''" readonly></label></section><section><h2>4.　Responsibility</h2><label>At Fault - Name<input v-model="f.at_fault_name"></label><label>At Fault - Position<select v-model="f.at_fault_position"><option>Driver</option><option>Third Party</option><option>Company</option><option>Unknown</option></select></label></section><section><h2>5.　Repair & Billing</h2><label>Repair Shop<input v-model="f.repair_shop"></label><label>Invoice No.<input v-model="f.invoice_no"></label><label>Subtotal Repair Cost<input v-model="f.subtotal_repair_cost" type="number"></label><label>Sales Tax (13%)<input v-model="f.sales_tax_amount" type="number"></label><label>Total Paid<input v-model="f.total_cost" type="number"></label><label>Payment Method<select v-model="f.payment_method"><option>Insurance</option><option>Card</option><option>Cash</option></select></label></section><section><h2>6.　Notes & Actions</h2><label class="wide">Notes<textarea v-model="f.notes"></textarea></label><label class="wide">Immediate Actions Taken<textarea></textarea></label></section><section><h2>7.　Follow Up</h2><label>Follow Up Required?<select><option>No</option><option>Yes</option></select></label><label>Additional Notes<textarea></textarea></label></section></div><footer><button class="btn btn-success" @click="save">Save</button><button class="btn btn-primary">Save PDF</button><button class="btn btn-outline-secondary" @click="entry=false">Cancel</button></footer></template></main></div></div></template>
<script setup>import{computed,onMounted,reactive,ref}from'vue';import AppSidebar from'../components/AppSidebar.vue';import client from'../api/client';const open=ref(false),hidden=ref(false),entry=ref(false),search=ref(''),rows=ref([]),vehicles=ref([]),drivers=ref([]);const f=reactive({report_date:new Date().toISOString().slice(0,10),created_by_name:'John Anderson',incident_report_no:'',incident_report_name:'',incident_date:new Date().toISOString().slice(0,10),incident_time:'',location:'',accident_type:'Collision',description:'',vehicle_id:'',driver_id:'',at_fault_name:'',at_fault_position:'Unknown',repair_shop:'',invoice_no:'',subtotal_repair_cost:0,sales_tax_amount:0,total_cost:0,payment_method:'Insurance',notes:'',status:1});const vehicle=computed(()=>vehicles.value.find(v=>v.id==f.vehicle_id));const stats=computed(()=>[{l:'Total Incidents',v:rows.value.length,s:'All time',icon:'▧',t:'all'},{l:'Closed',v:rows.value.filter(x=>x.status==2).length,s:'of total',icon:'✓',t:'closed'},{l:'Under Review',v:rows.value.filter(x=>x.status==3).length,s:'of total',icon:'◷',t:'review'},{l:'Open',v:rows.value.filter(x=>x.status==1).length,s:'of total',icon:'◌',t:'opened'},{l:'Collisions',v:rows.value.filter(x=>x.accident_type==='Collision').length,s:'of total',icon:'▱',t:'collision'}]);const date=x=>x?new Date(x).toLocaleDateString():'—';async function load(){rows.value=(await client.get('/accident-reports',{params:{per_page:50,search:search.value}})).data.data.data;vehicles.value=(await client.get('/vehicles',{params:{per_page:200}})).data.data.data;drivers.value=(await client.get('/drivers',{params:{per_page:200}})).data.data.data}async function save(){await client.post('/accident-reports',{...f,vehicle_id:+f.vehicle_id,driver_id:f.driver_id?+f.driver_id:null});entry.value=false;load()}onMounted(load)</script>
<style scoped>.ac header{display:flex;justify-content:space-between;margin-bottom:16px}.ac h1{margin:0;color:#071a85;font-size:27px}.ac header p{color:#0739d2;font-size:13px}.summary{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.summary article{display:flex;gap:14px;border:1px solid #dce7f8;border-radius:6px;padding:12px}.summary b{font-size:26px}.summary strong,.summary small{display:block}.summary strong{font-size:23px}.summary small{font-size:10px}.closed{background:#f1fff5}.review{background:#fffaf0}.opened{background:#f2f7ff}.collision{background:#fff7ff}.filter{display:grid;grid-template-columns:2fr repeat(5,1fr) .7fr;gap:12px;padding:16px;margin-top:16px;border:1px solid #e2e9f5}.filter input,.filter select,.filter button{height:36px;border:1px solid #dbe5f4;border-radius:4px;padding:6px}.table{margin-top:12px;overflow:auto}.table table{width:100%;border-collapse:collapse;font-size:11px}.table th,.table td{border-bottom:1px solid #e7edf7;padding:10px;white-space:nowrap;text-align:left}.table th{color:#071a7c}.table em{padding:4px 8px;border-radius:4px;font-style:normal}.s1{background:#e3efff;color:#064ce5}.s2{background:#e4f8e8;color:#087d30}.s3{background:#fff2d8;color:#e78b00}.form{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.form section{border:1px solid #e0e8f4;padding:13px;border-radius:7px}.form h2{font-size:14px;color:#073aed}.form label{display:inline-block;width:49%;padding:5px;font-size:11px;color:#061b78;font-weight:700}.form .wide{width:100%}.form input,.form select,.form textarea{display:block;width:100%;height:31px;border:1px solid #dce5f3;border-radius:4px;margin-top:4px}.form textarea{height:52px}footer{margin-top:12px;display:flex;gap:10px}@media(max-width:900px){.summary,.form,.filter{grid-template-columns:1fr}.form label{width:100%}}</style>
